#!/usr/bin/env bash\nset -e\n\n# Ensure the script is executable\nchmod +x ../entrypoint.sh\n\noutput=$(../entrypoint.sh)\n\n# The output should be non‑empty\nif [ -z "$output" ]; then\n  echo "Test failed: output is empty"\n  exit 1\nfi\n\n# The output should be one of the known tips\ngrep -Fxq "$output" ../tips.txt || {\n  echo "Test failed: output not in tips.txt"\n  exit 1\n}\n\necho "All tests passed"
